function showConsumerRegister(){setVerticalVIMode(false);document.querySelector('#app').innerHTML=shell(`<h1 class="screen-title">注册 GO ID</h1><div class="sub">注册后可一键建立只属于您的旅行信息库。</div><section class="card"><div class="field"><label for="regName">姓名</label><input id="regName" autocomplete="name" required></div><div class="field"><label for="regEmail">邮箱</label><input id="regEmail" type="email" autocomplete="email" required></div><div class="field"><label for="regPhone">手机号（选填）</label><input id="regPhone" type="tel" autocomplete="tel"></div><div class="field"><label for="regPwd">设置密码</label><input id="regPwd" type="password" minlength="10" autocomplete="new-password" required></div><label style="display:flex;gap:8px;align-items:flex-start;margin-top:12px"><input id="regTerms" type="checkbox"><span>我同意 GO 用户服务条款、隐私政策及个人旅行信息库规则。旅行资料仅在我授权的旅行用途下释放。</span></label><button class="btn primary" id="doRegister" style="margin-top:14px">注册 GO ID</button><button class="btn ghost" id="backLogin" style="margin-top:8px">返回登录</button></section>`,'home');bindNav();$('#backLogin').onclick=showAuth;$('#doRegister').onclick=async()=>{if(!$('#regTerms').checked){toast('请先阅读并同意注册条款');return}try{const terms={consumer_service_terms:'2026-08-25-v1',privacy_policy:'2026-08-25-v1',personal_vault_terms:'2026-08-25-v1'};await api('/v1/consumer/auth/register',{method:'POST',body:JSON.stringify({email:$('#regEmail').value,password:$('#regPwd').value,display_name:$('#regName').value,phone:$('#regPhone').value||null,accepted_terms:true,term_versions:terms})});await bootstrapConsumer();showAccount(true)}catch(e){toast(e.message)}}}

