function showHomeMobilityChooser(){uxCloseSheet();const wrap=document.createElement('div');wrap.className='ux-sheet-backdrop';wrap.innerHTML=`<section class="ux-sheet" role="dialog" aria-modal="true" aria-labelledby="mobilityTitle"><div class="ux-sheet-handle"></div><h2 id="mobilityTitle">出行用车</h2><p class="muted">租车与接送共用一个首页入口。</p><div class="actions"><button class="btn ghost" id="homeRental">租车</button><button class="btn ghost" id="homeRide">接送</button></div><button class="btn ghost" id="homeMobilityCancel" style="margin-top:8px">取消</button></section>`;document.body.appendChild(wrap);wrap.onclick=e=>{if(e.target===wrap)uxCloseSheet()};wrap.querySelector('#homeRental').onclick=()=>{uxCloseSheet();showRentalSearch()};wrap.querySelector('#homeRide').onclick=()=>{uxCloseSheet();showRideSearch()};wrap.querySelector('#homeMobilityCancel').onclick=uxCloseSheet}
function showHome(focus=false){setVerticalVIMode(false);if(focus){showHotelSearch();return}state.screen='home';document.querySelector('#app').innerHTML=frozenHomeDomShell(`<section class="go-category-nav frozen-category-nav" aria-label="旅行品类"><button class="active" data-home-vertical="HOTEL"><img src="/go-app/assets/icons/hotel.svg" alt=""><span>酒店</span></button><button data-home-vertical="FLIGHT"><img src="/go-app/assets/icons/flight.svg" alt=""><span>机票</span></button><button data-home-vertical="RAIL"><img src="/go-app/assets/icons/rail.svg" alt=""><span>火车票</span></button><button data-home-vertical="MOBILITY"><img src="/go-app/assets/icons/rental.svg" alt=""><span>租车</span></button><button data-home-vertical="ATTRACTION"><img src="/go-app/assets/icons/attraction.svg" alt=""><span>景点玩乐</span></button></section><section class="go-dual-entry frozen-dual-entry"><article class="go-feature-card go-ai-card"><img class="go-feature-brand" src="/go-app/assets/go-ai.svg" alt="GO AI"><h1>说出你的旅行想法</h1><p>AI 懂你的需求<br>帮你找到最合适的方案</p><div class="go-voice-wrap"><span class="go-glow g3"></span><span class="go-glow g2"></span><span class="go-glow g1"></span><button class="go-voice-button blue" id="aiEntry" aria-label="进入 GO AI"><img class="mic" src="/go-app/assets/icons/mic.svg" alt=""><img class="voice-go" src="/go-app/assets/go-symbol-on-color.svg" alt="GO"></button></div></article><article class="go-feature-card go-offer-card"><img class="go-feature-brand go-offer-brand" src="/go-app/assets/go-offer.svg" alt="GO Offer"><h1>告诉酒店您的需求</h1><p>多间 · 多晚 · 团队 · 会议<br>让合适的酒店为您的团队报价</p><div class="go-voice-wrap"><span class="go-glow g3 orange"></span><span class="go-glow g2 orange"></span><span class="go-glow g1 orange"></span><button class="go-voice-button orange" id="offerEntry" aria-label="进入 GO Offer"><img class="mic" src="/go-app/assets/icons/mic.svg" alt=""><img class="voice-go" src="/go-app/assets/go-symbol-on-color.svg" alt="GO"></button></div></article></section><section class="go-trust-layer frozen-trust-layer"><div><b><img src="/go-app/assets/go-symbol.svg" alt="GO">直连</b><small>直连官方<br>交易更直接</small></div><div><b><img src="/go-app/assets/go-symbol.svg" alt="GO">推荐</b><small>独立判断<br>只推荐值得的</small></div><div><b><img src="/go-app/assets/go-symbol.svg" alt="GO">礼遇</b><small>官方专享<br>尊享更多礼遇</small></div></section><section class="go-recommendations frozen-recommendations"><div class="go-reco-head"><h2><img src="/go-app/assets/go-symbol.svg" alt="GO">推荐</h2><button type="button" id="discoverMore">查找酒店 <span>›</span></button></div><div class="go-reco-track"><article class="go-reco-card reco-photo reco-kyoto-photo"><span class="go-reco-badge">旅行灵感</span><div class="go-reco-copy"><h3>京都 · 山间静居</h3><p>安静地住进岚山</p><div class="go-rating">旅行灵感 · 示意</div></div></article><article class="go-reco-card reco-photo reco-maldives-photo"><span class="go-reco-badge">旅行灵感</span><div class="go-reco-copy"><h3>马尔代夫 · 海岛假日</h3><p>印度洋上的私密假期</p><div class="go-rating">旅行灵感 · 示意</div></div></article><article class="go-reco-card reco-photo reco-lisbon-photo"><span class="go-reco-badge">旅行灵感</span><div class="go-reco-copy"><h3>里斯本 · 街巷向海</h3><p>街巷、日落与海风</p><div class="go-rating">旅行灵感 · 示意</div></div></article></div><div class="go-pager"><i class="on"></i><i></i><i></i></div></section>`);bindHomeNav();document.querySelectorAll('[data-home-vertical]').forEach(b=>b.onclick=()=>{const v=b.dataset.homeVertical;if(v==='HOTEL')showHotelSearch();else if(v==='FLIGHT')showFlightSearch();else if(v==='RAIL')showRailSearch();else if(v==='MOBILITY')showHomeMobilityChooser();else if(v==='ATTRACTION')showAttractionSearch()});$('#aiEntry').onclick=()=>showExplore();$('#offerEntry').onclick=()=>toast('团队报价暂未开放，请先查询酒店或稍后再试');$('#discoverMore').onclick=()=>showHotelSearch()}
function showHotelSearch(){setVerticalVIMode(true);state.screen='search';document.querySelector('#app').innerHTML=homeShell(`<section class="go-page-head"><button class="go-back" id="txBack" aria-label="返回">‹</button><div><span>酒店</span><h1>搜索酒店</h1></div></section><section class="go-form-card"><div class="field wide"><label for="city">目的地 / 酒店</label><input id="city" placeholder="城市、商圈、地标或酒店"></div><div class="date-pair"><div class="field"><label for="cin">入住</label><input id="cin" type="date"></div><div class="field"><label for="cout">退房</label><input id="cout" type="date"></div></div><div class="field wide"><label>房间与住客</label><div class="fake-input">1间房 · 2位成人</div></div><div class="quick-filters"><button>GO 推荐</button><button>官方直连</button><button>含早餐</button><button>可取消</button></div><button class="btn primary tx-submit" id="searchBtn">查询酒店</button></section>`,'home');bindHomeNav();$('#txBack').onclick=showHome;$('#searchBtn').onclick=search}
function showFlightSearch(){setVerticalVIMode(true);state.screen='flight';document.querySelector('#app').innerHTML=homeShell(`<section class="go-page-head"><button class="go-back" id="txBack" aria-label="返回">‹</button><div><span>机票</span><h1>搜索航班</h1></div></section><section class="go-form-card"><div class="trip-tabs"><button class="active">单程</button><button disabled>往返</button><button disabled>多程</button></div><div class="route-row"><div class="field"><label for="forigin">出发地</label><input id="forigin" placeholder="哈尔滨 / HRB"></div><span>→</span><div class="field"><label for="fdest">目的地</label><input id="fdest" placeholder="福州 / FOC"></div></div><div class="field wide"><label for="fdate">出发日期</label><input id="fdate" type="date"></div><div class="field wide"><label>乘机人 / 舱等</label><div class="fake-input">1位成人 · 经济舱</div></div><button class="btn primary tx-submit" id="flightSearchBtn">查询航班</button></section>`,'home');bindHomeNav();$('#txBack').onclick=showHome;$('#flightSearchBtn').onclick=searchFlights}
async function searchFlights(){try{const body={origin:$('#forigin').value.trim()||'HRB',destination:$('#fdest').value.trim()||'FOC',departure_date:$('#fdate').value,cabin:'ECONOMY',currency:'CNY'};if(!body.departure_date){toast('请选择出发日期');return}state.flightCriteria=body;const d=await api('/v1/flights/search',{method:'POST',body:JSON.stringify(body)});state.flightSearch=d.items||[];renderFlightResults(d.comparison_basis||[])}catch(e){toast(e.message)}}
function renderFlightResults(basis=[]){const items=state.flightSearch||[];const cards=items.map((o,i)=>{const seg=(o.segments||[])[0]||{};const change=o.change_policy||{},refund=o.refund_policy||{},bag=o.baggage||{};return `<article class="flight-row" data-flight="${o.offer_id}"><div class="flight-times"><div><b>${safe(seg.departure_time)}</b><small>${safe(seg.origin||o.origin)}</small></div><div class="flight-line"><span>${minutesLabel(seg.duration_minutes)}</span><i></i><small>直飞</small></div><div><b>${safe(seg.arrival_time)}</b><small>${safe(seg.destination||o.destination)}</small></div></div><div class="flight-meta"><span>${safe(o.carrier_code)} ${safe(o.flight_number)}</span><span>${safe(o.fare_family,'经济舱')}</span><span>${bag.checked_bag_kg?`托运行李 ${bag.checked_bag_kg}KG`:'无免费托运行李'}</span></div><div class="flight-bottom"><div class="policy-badges"><span>${change.allowed?'可改签':'不可改签'}</span><span>${refund.allowed?'可退票':'不可退票'}</span></div><div><strong>${money(o.total_amount_minor,o.currency)}</strong><button class="mini-select">选</button></div></div></article>`}).join('');$('#app').innerHTML=shell(`<section class="list-head"><button class="plain-back" id="back">‹</button><div><h1>${safe(state.flightCriteria?.origin)} → ${safe(state.flightCriteria?.destination)}</h1><p>${zhDate(state.flightCriteria?.departure_date)} · 1位成人 · 经济舱</p></div></section><div class="sort-row"><button class="active">GO 推荐</button><button>时间</button><button>价格</button><button>筛选</button></div><section class="comparison-note">比较口径：${basis.map(consumerLabel).join(' · ')||'总价 · 行李 · 退改 · 总旅行时间'}</section>${cards||consumerEmpty('没有可用航班','当前没有返回可验证的航班报价。','修改搜索','flightBack')}`,'search');bindNav();$('#back').onclick=showFlightSearch;document.querySelectorAll('[data-flight]').forEach(x=>x.onclick=()=>renderFlightOffer(x.dataset.flight));if($('#flightBack'))$('#flightBack').onclick=showFlightSearch}
function renderFlightOffer(id){const o=(state.flightSearch||[]).find(x=>x.offer_id===id);if(!o)return;state.flightOffer=o;const s=(o.segments||[])[0]||{},bag=o.baggage||{},ch=o.change_policy||{},rf=o.refund_policy||{};$('#app').innerHTML=shell(`<section class="list-head"><button class="plain-back" id="back">‹</button><div><h1>${safe(o.origin)} → ${safe(o.destination)}</h1><p>${zhDate(o.departure_date)} · ${safe(o.fare_family)}</p></div></section><section class="card fare-card"><div class="flight-times large"><div><b>${safe(s.departure_time)}</b><small>${safe(s.origin)}</small></div><div class="flight-line"><span>${minutesLabel(s.duration_minutes)}</span><i></i><small>直飞</small></div><div><b>${safe(s.arrival_time)}</b><small>${safe(s.destination)}</small></div></div><div class="kv"><span>航班</span><b>${safe(o.carrier_code)} ${safe(o.flight_number)}</b></div><div class="kv"><span>托运行李</span><b>${bag.checked_bag_kg?bag.checked_bag_kg+'KG':'无免费托运行李'}</b></div><div class="kv"><span>手提行李</span><span>${bag.cabin_bag_kg?bag.cabin_bag_kg+'KG':'待确认'}</span></div><div class="kv"><span>改签</span><span>${ch.allowed?`允许${ch.fee_minor?` · 费用${money(ch.fee_minor,o.currency)}起`:''}`:'不可改签'}</span></div><div class="kv"><span>退票</span><span>${rf.allowed?`允许${rf.fee_minor?` · 费用${money(rf.fee_minor,o.currency)}起`:''}`:'不可退票'}</span></div><div class="fare-total"><span>含税总价</span><strong>${money(o.total_amount_minor,o.currency)}</strong></div><button class="btn primary" id="flightContinue">继续</button></section><section class="evidence-card"><b>交易事实</b><p>下单前 GO 会重新核验价格、库存和退改规则。外部航司/票务执行未通过认证时不会生成“出票成功”。</p></section>`,'search');bindNav();$('#back').onclick=()=>renderFlightResults();$('#flightContinue').onclick=prebookFlight}
async function prebookFlight(){try{if(!state.me){toast('请先登录 GO ID');showAuth();return}state.flightPrebook=await api(`/v1/flights/offers/${state.flightOffer.offer_id}/prebook`,{method:'POST'});renderFlightReview()}catch(e){toast(e.message)}}
function renderFlightReview(){const o=state.flightOffer,p=state.flightPrebook,s=(o.segments||[])[0]||{};$('#app').innerHTML=shell(`<section class="list-head"><button class="plain-back" id="back">‹</button><div><h1>核对机票订单</h1><p>支付前最终确认</p></div></section><section class="card order-review"><div class="kv"><span>行程</span><b>${safe(o.origin)} → ${safe(o.destination)}</b></div><div class="kv"><span>时间</span><span>${zhDate(o.departure_date)} ${safe(s.departure_time)}–${safe(s.arrival_time)}</span></div><div class="kv"><span>运价产品</span><b>${safe(o.fare_family)}</b></div><div class="kv"><span>乘机人</span><span>${safe(state.me?.display_name||'GO Traveler')}</span></div><div class="kv"><span>含税总价</span><b>${money(p.total_amount_minor,p.currency)}</b></div><div class="kv"><span>报价有效</span><span>${new Date(p.expires_at).toLocaleString()}</span></div><div class="critical-note">本页仅表示报价与库存已预核验，不表示已出票或已付款。</div><button class="btn primary" id="flightOrderCreate">创建待支付订单</button></section>`,'search');bindNav();$('#back').onclick=()=>renderFlightOffer(o.offer_id);$('#flightOrderCreate').onclick=createFlightOrderAndCheckout}
async function search(){try{const body={destination:{city_code:$('#city').value.trim()},stay:{check_in:$('#cin').value,check_out:$('#cout').value},occupancy:{rooms:1,adults:2,children:0},currency:'CNY'};if(!body.destination.city_code||!body.stay.check_in||!body.stay.check_out){toast('请完整填写目的地和入住日期');return}state.searchCriteria=body;const d=await api('/v1/search/hotels',{method:'POST',body:JSON.stringify(body)});state.search=d.hotels;renderResults()}catch(e){toast(e.message)}}
function renderResults(){const criteria=state.searchCriteria||{},cards=(state.search||[]).map(h=>`<article class="hotel-result" data-hotel="${h.hotel_id}"><div class="hotel-art result-art"></div><div class="hotel-result-body"><div class="hotel-title-line"><h3>${safe(h.name,'酒店名称待返回')}</h3>${h.go_score?`<span class="go-score">GO ${h.go_score}</span>`:''}</div><p class="hotel-location">${safe(h.city,'目的地待返回')} ${h.area?'· '+h.area:''}</p><div class="result-tags"><span>${h.official_direct?'GO 官方直连':'授权来源'}</span>${h.guest_experience_score?`<span>住客 ${h.guest_experience_score}</span>`:''}<span>总价口径</span></div><div class="result-bottom"><small>${consumerLabel(h.recommendation_status||'NONE')}</small><strong>${money(h.best_offer?.total_amount_minor,h.best_offer?.currency||'CNY')}<em>起</em></strong></div></div></article>`).join('');$('#app').innerHTML=shell(`<section class="list-head"><button class="plain-back" id="back">‹</button><div><h1>${safe(criteria.destination?.city_code,'酒店')}</h1><p>${zhDate(criteria.stay?.check_in)}–${zhDate(criteria.stay?.check_out)} · 1间 · 2位成人</p></div></section><div class="sort-row"><button class="active">GO 推荐</button><button>位置</button><button>价格 / 星级</button><button>筛选</button></div><div class="filter-chips"><span>官方直连</span><span>含早餐</span><span>可取消</span><span>高评分</span></div>${cards||consumerEmpty('没有找到可售酒店','换一个目的地或日期继续搜索。','返回修改条件','resultBack')}`,'search');bindNav();$('#back').onclick=showHotelSearch;document.querySelectorAll('[data-hotel]').forEach(x=>x.onclick=()=>loadHotel(x.dataset.hotel));if($('#resultBack'))$('#resultBack').onclick=showHotelSearch}
async function loadHotel(id){try{const d=await api(`/v1/consumer/hotels/${id}`);state.hotel=d;renderHotel()}catch(e){toast(e.message)}}
function renderHotel(){const h=state.hotel||{},offers=h.offers||[];const hotelFeatures=(h.features||[]).slice(0,8);const grouped={};offers.forEach(o=>{const k=o.room_type_id||roomDisplay(o);(grouped[k]||(grouped[k]=[])).push(o)});const roomCards=Object.values(grouped).map(gs=>{const o=gs[0],facts=roomFacts(o),benefits=offerBenefits(o),lowest=gs.reduce((a,b)=>(a.total_amount_minor||Infinity)<(b.total_amount_minor||Infinity)?a:b,o);return `<article class="room-card"><div class="room-photo"></div><div class="room-main"><h3>${roomDisplay(o)}</h3><p class="room-facts">${facts.length?facts.join(' · '):'房型面积、床型与人数以酒店确认事实为准'}</p><div class="result-tags">${benefits.slice(0,4).map(x=>`<span>${x}</span>`).join('')}</div><div class="room-policy">${o.refundable?'可取消':'限制取消'}${o.cancellation_deadline?` · ${safe(o.cancellation_deadline)}前`:''}</div><div class="room-price"><span>${gs.length>1?`${gs.length}个可售方案`:sourceDisplay(o.source_type)}</span><strong>${money(lowest.total_amount_minor,lowest.currency)}<em>起</em></strong></div><button class="btn coral room-select" data-offer="${lowest.offer_id}">查看方案</button></div></article>`}).join('');$('#app').innerHTML=shell(`<section class="hotel-detail-head"><button class="plain-back" id="back">‹</button><div class="hotel-actions"><button>♡</button><button>分享</button></div></section><div class="hotel-hero"><div class="hotel-art detail-art"></div><div class="hero-pills"><span>亮点</span><span>点评</span><span>位置</span><span>相册</span></div></div><section class="hotel-summary-card"><h1>${safe(h.name)}</h1><div class="hotel-subline">${safe(h.city)}${h.area?' · '+h.area:''}</div><div class="facility-icons">${hotelFeatures.map(x=>`<span>${safe(x)}</span>`).join('')||'<span>设施信息待酒店确认</span>'}</div><div class="hotel-reason"><b>GO 为什么推荐</b><p>${safe(h.go_reason,'GO 将根据真实价格、履约与住客体验独立判断。')}</p></div></section><section class="stay-bar"><div><small>入住 / 退房</small><b>${zhDate(state.searchCriteria?.stay?.check_in)}–${zhDate(state.searchCriteria?.stay?.check_out)}</b></div><div><small>间数 / 人数</small><b>1间 · 2成人</b></div></section><section class="room-section"><div class="room-section-head"><h2>房型与官方报价</h2><button>筛选⌄</button></div>${roomCards||consumerEmpty('当前没有可用报价','返回搜索结果重新选择日期或酒店。','返回搜索结果','hotelOfferBack')}</section>`,'search');bindNav();$('#back').onclick=renderResults;document.querySelectorAll('[data-offer]').forEach(b=>b.onclick=()=>renderOfferCompare(b.dataset.offer));if($('#hotelOfferBack'))$('#hotelOfferBack').onclick=renderResults}
function renderOfferCompare(id){state.offer=state.hotel.offers.find(x=>x.offer_id===id);const o=state.offer,peers=(state.hotel.offers||[]).filter(x=>x.room_type_id===o.room_type_id);$('#app').innerHTML=shell(`<button class="back" id="back">← 房型</button><h1 class="screen-title">同房型比价</h1><div class="sub">只比较同房型、同餐食/取消/税费口径；来源与履约方必须明确。</div><section class="card"><div class="kv"><span>房型</span><b>${roomDisplay(o)}</b></div><div class="kv"><span>当前来源</span><b>${sourceDisplay(o.source_type)}</b></div><div class="kv"><span>当前总价</span><b>${money(o.total_amount_minor,o.currency)}</b></div></section><section class="card"><h2>可比报价</h2>${peers.map(x=>`<div class="offer"><div class="row"><div><b>${x.source_type||'授权来源'}</b><div class="muted" style="font-size:12px">${x.meal_plan} · ${x.refundable?'可退改':'限制退改'}</div></div><div class="price">${money(x.total_amount_minor,x.currency)}</div></div></div>`).join('')||consumerEmpty('当前只有一个可比报价','该房型暂时没有其他同口径报价，可继续选择当前报价。')}<button class="btn primary" id="continue">选择此报价并预订</button></section>`,'search');bindNav();$('#back').onclick=renderHotel;$('#continue').onclick=()=>selectOffer(id)}
async function selectOffer(id){try{state.offer=state.hotel.offers.find(x=>x.offer_id===id);state.prebook=await api(`/v1/offers/${id}/prebook`,{method:'POST',body:JSON.stringify({currency:state.offer.currency})});renderReviewOrder()}catch(e){toast(e.message)}}
function renderReviewOrder(){const o=state.offer,p=state.prebook;const benefits=offerBenefits(o);$('#app').innerHTML=shell(`<section class="list-head"><button class="plain-back" id="back">‹</button><div><h1>核对订单</h1><p>支付前最终确认</p></div></section><section class="card order-review"><div class="order-hotel"><b>${safe(state.hotel?.name)}</b><span>${roomDisplay(o)}</span></div><div class="kv"><span>入住日期</span><b>${zhDate(state.searchCriteria?.stay?.check_in)}–${zhDate(state.searchCriteria?.stay?.check_out)}</b></div><div class="kv"><span>房间 / 住客</span><span>1间 · 2位成人</span></div><div class="kv"><span>餐食</span><span>${safe(o.meal_plan,'以报价为准')}</span></div><div class="kv"><span>取消政策</span><span>${o.refundable?'可取消':'限制取消'}${o.cancellation_deadline?` · 截止 ${safe(o.cancellation_deadline)}`:''}</span></div>${benefits.length?`<div class="benefit-choice"><b>本单可享</b>${benefits.map(x=>`<span>✓ ${x}</span>`).join('')}</div>`:''}<div class="fare-total"><span>含税总价</span><strong>${money(p.total_amount_minor,p.currency)}</strong></div><div class="critical-note">${p.fare_rule?.data_mode==='SIMULATION'?'这是隔离测试方案，不产生真实预订或扣款。':'价格与库存已复核，请确认退改规则后继续。'}</div><div class="kv"><span>报价锁定至</span><span>${new Date(p.expires_at).toLocaleString()}</span></div><button class="btn primary" id="create">确认并继续支付</button></section>`,'search');bindNav();$('#back').onclick=renderHotel;$('#create').onclick=createOrder}
async function createOrder(){if(!state.me){toast('请先登录 GO ID');showAuth();return}try{state.order=await api('/v1/consumer/orders',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({prebook_id:state.prebook.prebook_id})});renderPay()}catch(e){toast(e.message)}}
function renderPay(){const o=state.order;$('#app').innerHTML=shell(`<button class="back" id="back">← 订单核对</button><h1 class="screen-title">选择支付渠道</h1><div class="sub">渠道切换必须由你确认；状态未知时不会重复扣款</div><section class="card"><div class="row"><div><b>应付总额</b><div class="price">${money(o.total_amount_minor,o.currency)}</div></div><span class="status">预授权</span></div><div class="field" style="margin:18px 0"><label for="payChannel">支付渠道</label><select id="payChannel"><option value="ALIPAY">支付宝</option><option value="WECHAT_PAY">微信支付</option><option value="UNIONPAY_QUICKPASS">银联云闪付</option><option value="VISA">Visa</option><option value="MASTERCARD">Mastercard</option><option value="APPLE_PAY">Apple Pay</option><option value="GOOGLE_PAY">Google Pay</option></select></div><button class="btn primary" id="pay">继续到渠道</button></section>`,'search');bindNav();$('#back').onclick=renderReviewOrder;$('#pay').onclick=checkout}
async function checkout(){try{const channels=['ALIPAY','WECHAT_PAY','UNIONPAY_QUICKPASS','VISA','MASTERCARD','AMEX','JCB','UNIONPAY_CARD','APPLE_PAY','GOOGLE_PAY'];const i=await api('/v1/payments/intents',{method:'POST',headers:{'Idempotency-Key':`hotel:${state.order.order_id}:authorize`},body:JSON.stringify({business_type:'HOTEL_ORDER',business_id:state.order.order_id,payee_id:state.order.supplier_id||'GO_HOTEL_CLEARING',operation:'AUTHORIZE',amount_minor:state.order.total_amount_minor,currency:state.order.currency,channel_priority:channels})});state.paymentIntent=await api(`/v1/payments/intents/${i.payment_intent_id}/channel`,{method:'POST',body:JSON.stringify({channel:$('#payChannel').value})});const r=await api(`/v1/payments/intents/${i.payment_intent_id}/checkout-readiness`);renderPaymentReadiness(r)}catch(e){toast(e.message)}}
function renderPaymentReadiness(r){$('#app').innerHTML=shell(`<h1 class="screen-title">支付渠道尚未启用</h1><section class="card"><div class="kv"><span>当前支付</span><b>尚未完成</b></div><div class="kv"><span>渠道</span><span>${consumerLabel(r.channel)}</span></div><div class="kv"><span>状态</span><b>${consumerLabel(r.state)}</b></div><p class="muted">未产生扣款，未确认预订。请稍后重试或选择其他已认证渠道。</p><button class="btn ghost" id="retry">返回选择渠道</button></section>`,'search');bindNav();$('#retry').onclick=renderPay}
function renderSuccess(){$('#app').innerHTML=shell(`<section class="card" style="text-align:center;padding:36px 22px"><div style="font-size:58px;color:#176b45">✓</div><h1>预订成功</h1><p class="muted">酒店已确认，支付已完成 确认扣款。</p><div class="kv"><span>确认号</span><b>${state.order.supplier_confirmation_no}</b></div><div class="kv"><span>订单号</span><span>${state.order.order_id}</span></div><button class="btn primary" id="trip">查看 GO Trips</button></section>`,'trips');bindNav();$('#trip').onclick=showUnifiedTrips}
async function showUnifiedTrips(){setVerticalVIMode(false);try{const d=await api('/v1/consumer/unified-trips'),rows=d.items||[];$('#app').innerHTML=shell(`<h1 class="screen-title">GO Trips</h1><div class="sub">航班、铁路、酒店、用车、租车与景点统一事实入口</div>${rows.map(x=>`<section class="card"><div class="row"><h3>${safe(x.title)}</h3><span class="status">${safe(consumerLabel(x.lifecycle_state))}</span></div><div class="kv"><span>品类</span><b>${safe(consumerLabel(x.vertical))}</b></div><div class="kv"><span>支付</span><span>${safe(consumerLabel(x.payment_state))}</span></div><div class="kv"><span>退款</span><span>${safe(consumerLabel(x.refund_state))}</span></div>${window.GODirectAfterSales.tripLink(x)?`<a class="btn ghost" href="${safe(window.GODirectAfterSales.tripLink(x))}">查看入住与售后</a>`:''}</section>`).join('')||consumerEmpty('还没有可验证的行程','完成预订后，酒店、机票、铁路、用车、租车与门票会统一进入 GO Trips。','返回首页','emptyHome')}`,'trips');bindNav()}catch(e){$('#app').innerHTML=shell(`<h1 class="screen-title">GO Trips</h1><div class="empty">行程加载失败。<button class="btn ghost" id="tripRetry">重试</button></div>`,'trips');bindNav();$('#tripRetry').onclick=showUnifiedTrips}}
async function showTrips(){try{const d=await api('/v1/consumer/trips');state.trips=d.items;const cards=state.trips.map(t=>`<section class="card" data-trip="${t.order_id}"><div class="row"><h3 style="margin:0">${t.hotel_name}</h3><span class="status">${consumerLabel(t.status)}</span></div><div class="muted" style="font-size:12px;margin:7px 0">${t.order_id}</div><div class="row"><b>${money(t.total_amount_minor,t.currency)}</b><span class="muted">${t.refund?`退款 ${consumerLabel(t.refund.status)}`:t.stay_credit?`住宿额度 ${consumerLabel(t.stay_credit.status)}`:'查看详情 →'}</span></div></section>`).join('');$('#app').innerHTML=shell(`<h1 class="screen-title">GO Trips</h1><div class="sub">预订、退改、退款与Credit统一事实入口</div>${cards||consumerEmpty('还没有订单','完成一次预订后，订单会出现在这里。','返回首页','tripHome')}`,'trips');bindNav();document.querySelectorAll('[data-trip]').forEach(x=>x.onclick=()=>showTrip(x.dataset.trip));if($('#tripHome'))$('#tripHome').onclick=showHome}catch(e){toast(e.message)}}
async function showTrip(id){try{state.detail=await api(`/v1/consumer/orders/${id}/detail`);renderTrip()}catch(e){toast(e.message)}}
function renderTrip(){const d=state.detail,o=d.order;const manageable=['CONFIRMED'].includes(o.status)&&!d.supplier_remedy&&!d.credit_redemption&&!d.stay_credits.length;$('#app').innerHTML=shell(`<button class="back" id="back">← GO Trips</button><section class="card"><div class="row"><h2 style="margin:0">${o.hotel_name||'酒店名称待返回'}</h2><span class="status">${consumerLabel(o.status)}</span></div><div class="kv"><span>订单号</span><span>${o.order_id}</span></div><div class="kv"><span>确认号</span><b>${o.supplier_confirmation_no||'等待供应商确认'}</b></div><div class="kv"><span>金额</span><b>${money(o.total_amount_minor,o.currency)}</b></div>${d.stay?`<div class="kv"><span>入住</span><span>${d.stay.check_in} → ${d.stay.check_out}</span></div>`:''}</section>${window.GOCatalogFare?.card(d.fare_rule,o,money)||''}${window.GOCatalogCashFare?.progress(d.cash_after_sales,money)||''}${window.GODirectAfterSales?.disruption(d.supplier_remedy,o.currency)||''}<section class="card actions"><h3>管理订单</h3><button class="btn ghost" id="change" ${!manageable?'disabled':''}>改期 + 补差价</button><button class="btn ghost" id="credit" ${!manageable?'disabled':''}>查看本店住宿额度转换</button><button class="btn danger" id="cancel" ${!manageable?'disabled':''}>取消 / 查看退款</button></section>${d.refunds.length&&d.cash_after_sales?.action!=='CANCEL'?`<section class="card"><h3>退款</h3>${d.refunds.map(r=>`<div class="kv"><span>${consumerLabel(r.status)}</span><b>${money(r.amount_minor,r.currency)}</b></div>`).join('')}</section>`:''}${window.GOCatalogCredit?.cards(d.stay_credits,o.currency)||''}${window.GOCatalogCredit?.redemptionCard(d.credit_redemption)||''}<section class="card"><h3>订单时间线</h3><div class="timeline">${d.timeline.slice(-12).map(e=>`<div><b>${consumerLabel(e.event_type)}</b><br><span class="muted">${new Date(e.occurred_at).toLocaleString()}</span></div>`).join('')}</div></section>`,'trips');bindNav();$('#back').onclick=showTrips;window.GOCatalogCredit?.bind(catalogCreditContext());window.GOCatalogCashFare?.bind(cashFareContext(),d.cash_after_sales);if($('#change'))$('#change').onclick=changeFlow;if($('#cancel'))$('#cancel').onclick=cancelFlow;if($('#credit'))$('#credit').onclick=creditFlow;const remedy=$('#retrySupplierRemedy');if(remedy)remedy.onclick=async()=>{if(remedy.disabled)return;remedy.disabled=true;try{await api(`/v1/consumer/orders/${encodeURIComponent(o.order_id)}/supplier-cancellation-remedy/retry`,{method:'POST'});await showTrip(o.order_id)}catch(e){toast(e.message);remedy.disabled=false}}}
function cashFareContext(){return {api,money,dialog:window.GOBooking.dialog,container:$('#app'),toast,reload:showTrip}}
async function changeFlow(){try{await window.GOCatalogCashFare.change(cashFareContext(),state.detail.order,state.detail.stay)}catch(e){toast(e.message)}}
async function cancelFlow(){try{await window.GOCatalogCashFare.cancel(cashFareContext(),state.detail.order)}catch(e){toast(e.message)}}
function catalogCreditContext(){return {container:$('#app'),api,money,toast,onBack:()=>showTrip(state.detail.order.order_id),onOrder:showTrip,render:html=>{$('#app').innerHTML=shell(html,'trips');bindNav()}}}
async function creditFlow(){try{return await window.GOCatalogCredit.convert(catalogCreditContext(),state.detail.order)}catch(e){toast(e.message)}}
async function showPendingReview(){try{const list=await api('/v1/consumer/reviews/pending');if(!list.length){$('#app').innerHTML=shell(`<h1 class="screen-title">点评</h1>${consumerEmpty('暂无待点评入住','完成入住后，GO 会在合适时机邀请你评价。','查看订单','reviewTrips')}`,'review');bindNav();$('#reviewTrips').onclick=showUnifiedTrips;return}state.review=list[0];await api(`/v1/consumer/reviews/${state.review.review_id}/second-trigger`,{method:'POST'});renderReview()}catch(e){toast(e.message)}}
function renderReview(){const r=state.review;const issues=[['CHECKIN_WAIT_TOO_LONG','入住等待'],['ROOM_NOT_CLEAN','房间清洁'],['SERVICE_SLOW','服务响应'],['NOISE_SLEEP','睡眠/噪音'],['BENEFIT_NOT_HONORED','权益未兑现'],['SERIOUS_HYGIENE','严重卫生'],['SAFETY','安全问题'],['ABNORMAL_CHARGE','异常收费']];$('#app').innerHTML=shell(`<h1 class="screen-title">上次入住怎么样？</h1><div class="sub">像 Uber 一样快速完成；低分需要说明具体发生了什么。</div><section class="card"><div class="stars">${[1,2,3,4,5].map(n=>`<button data-star="${n}" class="${state.stars>=n?'on':''}">★</button>`).join('')}</div><div id="issues" style="display:${state.stars&&state.stars<=3?'block':'none'}"><h3>发生了什么？</h3><div class="issue-grid">${issues.map(x=>`<button class="issue ${state.tags.includes(x[0])?'selected':''}" data-tag="${x[0]}">${x[1]}</button>`).join('')}</div><button class="btn primary" id="submitLow" style="margin-top:14px">提交评价</button></div><div class="tiny" style="text-align:center;margin-top:14px">1–5星是你的原始表达；GO Truth 正常公开体验分仍为3.0–5.0，严重问题独立进入风险事件。</div></section>`,'review');bindNav();document.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>submitStar(+b.dataset.star));document.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{const t=b.dataset.tag;state.tags=state.tags.includes(t)?state.tags.filter(x=>x!==t):[...state.tags,t].slice(0,5);renderReview()});if($('#submitLow'))$('#submitLow').onclick=submitLow}
async function submitStar(n){state.stars=n;try{const d=await api(`/v1/consumer/reviews/${state.review.review_id}/star`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({star:n})});if(n>=4){toast('评价完成，谢谢');state.stars=0;state.tags=[];setTimeout(showHome,700)}else{state.review=d;renderReview()}}catch(e){toast(e.message)}}
async function submitLow(){if(!state.tags.length){toast('请选择至少一个具体问题');return}try{await api(`/v1/consumer/reviews/${state.review.review_id}/tags`,{method:'POST',body:JSON.stringify({tags:state.tags})});await api(`/v1/consumer/reviews/${state.review.review_id}/complete`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}});toast('评价已提交；严重问题会进入独立核实链');state.stars=0;state.tags=[];setTimeout(showHome,800)}catch(e){toast(e.message)}}

async function createFlightOrderAndCheckout(){
 try{
  if(!state.me){showAuth();return}
  const o=await api('/v1/flights/orders',{method:'POST',body:JSON.stringify({prebook_id:state.flightPrebook.prebook_id,passengers:[{full_name:state.me.display_name||'GO Traveler',type:'ADT'}]})});
  await api(`/v1/flights/orders/${o.order_id}/checkout`,{method:'POST',body:JSON.stringify({payment_method_id:'pm_rc20_engineering_token'})});
  state.flightOrder=await api(`/v1/flights/orders/${o.order_id}`);renderFlightOrder();
 }catch(e){toast(e.message)}
}
function evHtml(e=[]){return e.length?e.slice(-8).map(x=>`<div class="kv"><span>#${x.sequence_no} ${safe(x.kind)}</span><b>${safe(x.status)}</b></div>`).join(''):'<p class="muted">暂无证据。</p>'}
function renderFlightOrder(){const o=state.flightOrder||{},i=(o.itinerary||[])[0]||{};$('#app').innerHTML=shell(`<h1 class="screen-title">机票订单</h1><section class="card"><div class="kv"><span>状态</span><b>${consumerLabel(o.status)}</b></div><div class="kv"><span>行程</span><b>${safe(i.origin)} → ${safe(i.destination)}</b></div><div class="kv"><span>PNR</span><span>${safe(o.pnr)}</span></div><div class="kv"><span>票号</span><span>${safe((o.ticket_numbers||[]).join(' / '))}</span></div><p class="muted">RC20 Staging 工程交易链；不代表真实航司生产出票或生产支付已启用。</p></section><section class="card"><button class="btn ghost" id="fchg" ${o.status!=='TICKETED'?'disabled':''}>改签</button><button class="btn danger" id="fref" ${o.status!=='TICKETED'?'disabled':''}>退票</button><button class="btn ghost" id="ftrips">GO Trips</button></section><section class="card"><h3>证据链</h3>${evHtml(o.evidence)}</section>`,'trips');bindNav();$('#ftrips').onclick=showUnifiedTrips;$('#fchg').onclick=flightChange;$('#fref').onclick=flightRefund}
async function flightReload(){state.flightOrder=await api(`/v1/flights/orders/${state.flightOrder.order_id}`);renderFlightOrder()}
function flightChange(){uxSheet({title:'机票改期',fields:[{id:'newDepartureDate',label:'新出发日期',type:'date'}],confirmLabel:'查看改期费用',onConfirm:async v=>{const q=await api(`/v1/flights/orders/${state.flightOrder.order_id}/change-quote`,{method:'POST',body:JSON.stringify({new_departure_date:v.newDepartureDate})});uxConfirm({title:'确认机票改期',summary:`<div class="kv"><span>补差及费用</span><b>${money(q.total_due_minor,q.currency)}</b></div>`,confirmLabel:'确认改期',onConfirm:async()=>{await api(`/v1/flights/orders/${state.flightOrder.order_id}/execute-change/${q.quote_id}`,{method:'POST'});await flightReload()}})}})}
async function flightRefund(){try{const q=await api(`/v1/flights/orders/${state.flightOrder.order_id}/refund-quote`);uxConfirm({title:'申请机票退款',summary:`<div class="kv"><span>预计退款</span><b>${money(q.refund_amount_minor,q.currency)}</b></div>`,confirmLabel:'确认退款',danger:true,onConfirm:async()=>{await api(`/v1/flights/orders/${state.flightOrder.order_id}/refund`,{method:'POST'});await flightReload()}})}catch(e){toast(e.message)}}

function showRailSearch(){setVerticalVIMode(true);state.screen='rail';$('#app').innerHTML=shell(`<section class="go-page-head"><button class="go-back" id="railBack" aria-label="返回">‹</button><div><span>火车票</span><h1>搜索车次</h1></div></section><section class="go-form-card"><div class="route-row"><div class="field"><label for="ro">出发站</label><input id="ro" placeholder="上海 / SHA"></div><span>→</span><div class="field"><label for="rd">到达站</label><input id="rd" placeholder="杭州 / HZH"></div></div><div class="field wide"><label for="rdate">出发日期</label><input id="rdate" type="date"></div><button class="btn primary" id="rgo">查询车次</button></section>`,'home');bindNav();$('#railBack').onclick=showHome;$('#rgo').onclick=railSearch}
async function railSearch(){try{const b={origin_station:$('#ro').value||'SHA',destination_station:$('#rd').value||'HZH',travel_date:$('#rdate').value,currency:'CNY'};if(!b.travel_date){toast('请选择日期');return}state.railCriteria=b;const d=await api('/v1/rail/search',{method:'POST',body:JSON.stringify(b)});state.railSearch=d.items||[];$('#app').innerHTML=shell(`<h1 class="screen-title">车次结果</h1>${state.railSearch.some(x=>x.external_live!==true)?'<p class="go-sim-note">以下为演示车次，价格和余票用于体验流程，暂不能购买真实车票。</p>':''}${state.railSearch.map(x=>`<section class="card" data-rail="${x.offer_id}"><div class="row"><h3>${safe(x.train_no)} · ${consumerLabel(x.seat_class)}</h3><b>${money(x.total_amount_minor,x.currency)} / 成人</b></div><div class="kv"><span>${safe(x.departure_time)} → ${safe(x.arrival_time)}</span><span>余票 ${x.inventory_left}</span></div><button class="btn primary">选择</button></section>`).join('')}`,'search');bindNav();document.querySelectorAll('[data-rail]').forEach(x=>x.onclick=()=>railSelect(x.dataset.rail))}catch(e){toast(e.message)}}
async function railSelect(id){toast('火车票预订组件尚未就绪，请刷新后重试。')}
function renderRailOrder(){const o=state.railOrder||{},j=o.journey||{};$('#app').innerHTML=shell(`<h1 class="screen-title">火车票订单</h1>${paymentDeadlineHtml(o)}<section class="card"><div class="kv"><span>状态</span><b>${consumerLabel(o.status)}</b></div><div class="kv"><span>车次</span><b>${safe(j.train_no)}</b></div><div class="kv"><span>席别</span><span>${safe(j.seat_class)}</span></div><div class="kv"><span>预订号</span><span>${safe(o.booking_reference)}</span></div><div class="kv"><span>人数 / 含税总价</span><span>${o.passenger_count||0} 人 · ${money(o.total_amount_minor,o.currency)}</span></div><p class="muted">隔离测试订单，不能用于实际乘车。</p></section><section class="card"><button class="btn ghost" id="rchg" ${o.status!=='TICKETED'?'disabled':''}>改签</button><button class="btn danger" id="rref" ${!['TICKETED','REFUND_PENDING'].includes(o.status)?'disabled':''}>${o.status==='REFUND_PENDING'?'继续核对原退款':'退票'}</button>${o.status==='CHANGE_PENDING'?'<button class="btn ghost" id="rresume">继续原改签申请</button>':''}${o.status==='PAYMENT_PENDING'?'<button class="btn danger" id="rcancelunpaid">取消未支付订单</button>':''}<button class="btn ghost" id="rtrips">GO Trips</button></section><section class="card"><h3>证据链</h3>${evHtml(o.evidence)}</section>`,'trips');bindNav();$('#rchg').onclick=railChange;$('#rref').onclick=railRefund;$('#rtrips').onclick=showUnifiedTrips;if($('#rcancelunpaid'))$('#rcancelunpaid').onclick=()=>cancelUnpaidVertical('RAIL');if($('#rresume'))$('#rresume').onclick=railResumeChange}
async function railResumeChange(){const o=state.railOrder,q=(o.change_quotes||[]).find(x=>x.status==='PREPARING');if(!q){toast('正在核对原改签申请，请稍后刷新。');return}uxConfirm({title:'继续原改签申请',description:'将继续处理已经提交的日期、席别和补款方案。',confirmLabel:'继续核对',onConfirm:async()=>{try{await api(`/v1/rail/orders/${encodeURIComponent(o.order_id)}/execute-change/${encodeURIComponent(q.quote_id)}`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}})}finally{await railReload()}}})}
async function railReload(){state.railOrder=await api(`/v1/rail/orders/${state.railOrder.order_id}`);renderRailOrder()}
function railChange(){uxSheet({title:'铁路改签',fields:[{id:'newTravelDate',label:'新出发日期',type:'date'}],confirmLabel:'查看改签费用',onConfirm:async v=>{const q=await api(`/v1/rail/orders/${state.railOrder.order_id}/change-quote`,{method:'POST',body:JSON.stringify({new_travel_date:v.newTravelDate,new_seat_class:state.railOrder.journey?.seat_class})});uxConfirm({title:'确认铁路改签',summary:`<div class="kv"><span>改签费用</span><b>${money(q.total_due_minor,q.currency)}</b></div>`,confirmLabel:'确认改签',onConfirm:async()=>{try{await api(`/v1/rail/orders/${state.railOrder.order_id}/execute-change/${q.quote_id}`,{method:'POST'})}finally{await railReload()}}})}})}
async function submitVerticalRefund(vertical,orderId){
 const group=vertical==='RAIL'?'rail':'attractions';
 try{return await api(`/v1/${group}/orders/${encodeURIComponent(orderId)}/refund`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}})}
 catch(e){if(/REFUND_ALREADY_PROCESSING|REFUND_LEASE_LOST/.test(e.message))throw new Error('原退款正在核对，请稍后刷新订单。');throw e}
 finally{const fresh=await api(`/v1/${group}/orders/${encodeURIComponent(orderId)}`);if(vertical==='RAIL'){state.railOrder=fresh;renderRailOrder()}else{state.attractionOrder=fresh;renderAttractionOrder()}}
}
function resumeVerticalRefund(vertical){
 const o=vertical==='RAIL'?state.railOrder:state.attractionOrder;
 return uxConfirm({title:'继续核对原退款',description:'原申请已受理。我们会继续核对同一笔退款，处理中暂不办理改签或核销。',confirmLabel:'核对退款进度',onConfirm:()=>submitVerticalRefund(vertical,o.order_id)});
}
async function railRefund(){if(state.railOrder?.status==='REFUND_PENDING')return resumeVerticalRefund('RAIL');try{const q=await api(`/v1/rail/orders/${state.railOrder.order_id}/refund-quote`);uxConfirm({title:'申请铁路退款',summary:`<div class="kv"><span>预计退款</span><b>${money(q.refund_amount_minor,q.currency)}</b></div>`,confirmLabel:'确认退款',danger:true,onConfirm:async()=>{await submitVerticalRefund('RAIL',state.railOrder.order_id)}})}catch(e){toast(e.message)}}

function showRideSearch(){showMobilitySearch('RIDE')}
function showRentalSearch(){showMobilitySearch('RENTAL')}
function showMobilitySearch(kind){setVerticalVIMode(true);const rental=kind==='RENTAL';state.screen=rental?'rental':'ride';$('#app').innerHTML=shell(`<section class="go-page-head"><button class="go-back" id="mobBack" aria-label="返回">‹</button><div><span>${rental?'租车':'用车'}</span><h1>${rental?'搜索租车':'搜索接送'}</h1></div></section><section class="go-form-card">${rental?`<div class="field"><label for="m1">取车地点</label><input id="m1" placeholder="东京 / NRT"></div><div class="field"><label for="m2">还车地点</label><input id="m2" placeholder="东京 / NRT"></div><div class="field"><label for="mt1">取车时间</label><input id="mt1" type="datetime-local"></div><div class="field"><label for="mt2">还车时间</label><input id="mt2" type="datetime-local"></div>`:`<div class="field"><label for="m1">上车地点</label><input id="m1" placeholder="上海浦东机场 / PVG"></div><div class="field"><label for="m2">目的地</label><input id="m2" placeholder="上海外滩"></div><div class="field"><label for="mt1">上车时间</label><input id="mt1" type="datetime-local"></div>`}<button class="btn primary" id="mgo">查询</button></section>`,'home');bindNav();$('#mobBack').onclick=showHome;$('#mgo').onclick=()=>mobilitySearch(kind)}
async function mobilitySearch(kind){try{const rental=kind==='RENTAL';let b;if(rental){b={pickup_location:$('#m1').value||'NRT',return_location:$('#m2').value||'NRT',pickup_at:$('#mt1').value,return_at:$('#mt2').value,currency:'CNY'}}else{b={pickup:$('#m1').value||'PVG',dropoff:$('#m2').value||'上海外滩',pickup_at:$('#mt1').value,currency:'CNY'}};if(!b.pickup_at||rental&&!b.return_at){toast('请填写时间');return}const d=await api(rental?'/v1/mobility/rentals/search':'/v1/mobility/rides/search',{method:'POST',body:JSON.stringify(b)});if(rental){state.rentalCriteria=b;state.rentalSearch=d.items||[]}else{state.rideCriteria=b;state.rideSearch=d.items||[]}const rows=(d.items||[]).map(x=>`<section class="card" data-mob="${x.offer_id}"><div class="row"><h3>${safe(x.vehicle_class)}</h3><b>${money(x.total_amount_minor,x.currency)}</b></div>${rental?`<div class="kv"><span>保险</span><span>${safe(x.insurance?.type)}</span></div><div class="kv"><span>押金</span><span>${money(x.deposit_minor,x.currency)}</span></div>`:`<div class="kv"><span>免费等待</span><span>${x.included_wait_minutes}分钟</span></div>`}<button class="btn primary">选择</button></section>`).join('');$('#app').innerHTML=shell(`<h1 class="screen-title">${rental?'租车':'接送'}方案</h1>${rows}`,'search');bindNav();document.querySelectorAll('[data-mob]').forEach(x=>x.onclick=()=>mobilityBook(kind,x.dataset.mob))}catch(e){toast(e.message)}}
async function mobilityBook(kind,id){try{if(!state.me){showAuth();return}const rental=kind==='RENTAL',b=rental?{...state.rentalCriteria,offer_id:id,drivers:[{name:state.me.display_name||'GO Traveler'}]}:{...state.rideCriteria,offer_id:id,passengers:[{name:state.me.display_name||'GO Traveler'}]};const o=await api(rental?'/v1/mobility/rentals/orders':'/v1/mobility/rides/orders',{method:'POST',body:JSON.stringify(b)});const d=await api(`/v1/mobility/orders/${o.order_id}`);if(rental)state.rentalOrder=d;else state.rideOrder=d;renderMobilityOrder(kind)}catch(e){toast(e.message)}}
function renderMobilityOrder(kind){const rental=kind==='RENTAL',o=rental?state.rentalOrder:state.rideOrder;$('#app').innerHTML=shell(`<h1 class="screen-title">${rental?'租车':'接送'}订单</h1><section class="card"><div class="kv"><span>状态</span><b>${consumerLabel(o.status)}</b></div><div class="kv"><span>车型</span><b>${safe(o.vehicle_class)}</b></div>${rental?`<div class="kv"><span>保险</span><span>${safe(o.insurance?.type)}</span></div><div class="kv"><span>押金</span><span>${money(o.deposit_minor,o.currency)}</span></div>`:`<div class="kv"><span>行程</span><span>${safe(o.pickup)} → ${safe(o.dropoff)}</span></div>`}<div class="kv"><span>供应确认</span><span>${safe(o.supplier_reference)}</span></div></section><section class="card"><button class="btn ghost" id="mmod" ${o.status!=='CONFIRMED'?'disabled':''}>修改时间</button><button class="btn ghost" id="mstart" ${o.status!=='CONFIRMED'?'disabled':''}>${rental?'确认取车':'确认上车'}</button><button class="btn ghost" id="mend" ${o.status!=='IN_PROGRESS'?'disabled':''}>${rental?'确认还车':'确认送达'}</button><button class="btn danger" id="mcancel" ${o.status!=='CONFIRMED'?'disabled':''}>取消并退款</button></section><section class="card"><h3>证据链</h3>${evHtml(o.evidence)}</section>`,'trips');bindNav();$('#mmod').onclick=()=>mobilityModify(kind);$('#mstart').onclick=()=>mobilityFulfill(kind,rental?'PICKUP':'START');$('#mend').onclick=()=>mobilityFulfill(kind,rental?'RETURN':'COMPLETE');$('#mcancel').onclick=()=>mobilityCancel(kind)}
async function mobilityReload(kind){const o=kind==='RENTAL'?state.rentalOrder:state.rideOrder;const d=await api(`/v1/mobility/orders/${o.order_id}`);if(kind==='RENTAL')state.rentalOrder=d;else state.rideOrder=d;renderMobilityOrder(kind)}
function mobilityModify(kind){const o=kind==='RENTAL'?state.rentalOrder:state.rideOrder;uxSheet({title:kind==='RENTAL'?'修改取车时间':'修改上车时间',fields:[{id:'newTime',label:'新时间',type:'datetime-local'}],confirmLabel:'确认修改',onConfirm:async v=>{await api(`/v1/mobility/orders/${o.order_id}/modify`,{method:'POST',body:JSON.stringify({new_time:v.newTime})});await mobilityReload(kind)}})}
async function mobilityFulfill(kind,action){const o=kind==='RENTAL'?state.rentalOrder:state.rideOrder;try{await api(`/v1/mobility/orders/${o.order_id}/fulfillment`,{method:'POST',body:JSON.stringify({action,evidence_reference:`CONSUMER_UI_${action}`})});await mobilityReload(kind)}catch(e){toast(e.message)}}
async function mobilityCancel(kind){const o=kind==='RENTAL'?state.rentalOrder:state.rideOrder;try{const q=await api(`/v1/mobility/orders/${o.order_id}/refund-quote`);uxConfirm({title:kind==='RENTAL'?'取消租车订单':'取消接送订单',summary:`<div class="kv"><span>预计退款</span><b>${money(q.refund_amount_minor,q.currency)}</b></div>`,confirmLabel:'确认取消',danger:true,onConfirm:async()=>{await api(`/v1/mobility/orders/${o.order_id}/cancel`,{method:'POST'});await mobilityReload(kind)}})}catch(e){toast(e.message)}}

function showAttractionSearch(){setVerticalVIMode(true);state.screen='attraction';$('#app').innerHTML=shell(`<section class="go-page-head"><button class="go-back" id="attrBack" aria-label="返回">‹</button><div><span>景点玩乐</span><h1>景点门票与体验</h1></div></section><section class="go-form-card"><div class="field"><label for="adest">目的地</label><input id="adest" placeholder="东京"></div><div class="field"><label for="adate">游玩日期</label><input id="adate" type="date"></div><button class="btn primary" id="ago">查询</button></section>`,'home');bindNav();$('#attrBack').onclick=showHome;$('#ago').onclick=attractionSearch}
async function attractionSearch(){try{const b={destination:$('#adest').value||'东京',visit_date:$('#adate').value,currency:'CNY'};if(!b.visit_date){toast('请选择日期');return}state.attractionCriteria=b;const d=await api('/v1/attractions/search',{method:'POST',body:JSON.stringify(b)});state.attractionSearch=d.items||[];$('#app').innerHTML=shell(`<h1 class="screen-title">门票与体验</h1>${state.attractionSearch.some(x=>x.external_live!==true)?'<p class="go-sim-note">以下为演示产品，价格和名额用于体验流程，暂不能购买真实门票。</p>':''}${state.attractionSearch.map(x=>`<section class="card" data-attr="${x.offer_id}"><div class="row"><h3>${safe(x.product_name)}</h3><b>${money(x.total_amount_minor,x.currency)} / 张</b></div><div class="kv"><span>场次</span><span>${safe(x.session_time)}</span></div><div class="kv"><span>库存</span><span>${x.inventory_units}</span></div><div class="kv"><span>凭证</span><span>${consumerLabel(x.voucher_type)}</span></div><button class="btn primary">选择</button></section>`).join('')}`,'search');bindNav();document.querySelectorAll('[data-attr]').forEach(x=>x.onclick=()=>attractionBook(x.dataset.attr))}catch(e){toast(e.message)}}
async function attractionBook(id){toast('门票预订组件尚未就绪，请刷新后重试。')}
function renderAttractionOrder(){const o=state.attractionOrder||{};$('#app').innerHTML=shell(`<h1 class="screen-title">门票 / 体验订单</h1>${paymentDeadlineHtml(o)}<section class="card"><div class="kv"><span>状态</span><b>${consumerLabel(o.status)}</b></div><div class="kv"><span>产品</span><b>${safe(o.product_name)}</b></div><div class="kv"><span>日期 / 场次</span><span>${safe(o.visit_date)} ${safe(o.session_time,'')}</span></div><div class="kv"><span>人数 / 含税总价</span><span>${o.quantity||0} 人 · ${money(o.total_amount_minor,o.currency)}</span></div><div class="kv"><span>核销凭证</span><b>${safe(o.voucher_code)}</b></div></section><section class="card"><button class="btn ghost" id="achg" ${o.status!=='CONFIRMED'?'disabled':''}>改期</button><button class="btn ghost" id="ared" ${o.status!=='CONFIRMED'?'disabled':''}>确认核销</button><button class="btn danger" id="aref" ${!['CONFIRMED','REFUND_PENDING'].includes(o.status)?'disabled':''}>${o.status==='REFUND_PENDING'?'继续核对原退款':'退款'}</button>${o.status==='PAYMENT_PENDING'?'<button class="btn danger" id="acancelunpaid">取消未支付订单</button>':''}</section><section class="card"><h3>证据链</h3>${evHtml(o.evidence)}</section>`,'trips');bindNav();$('#achg').onclick=attractionChange;$('#ared').onclick=attractionRedeem;$('#aref').onclick=attractionRefund;if($('#acancelunpaid'))$('#acancelunpaid').onclick=()=>cancelUnpaidVertical('ATTRACTION')}
async function attractionReload(){state.attractionOrder=await api(`/v1/attractions/orders/${state.attractionOrder.order_id}`);renderAttractionOrder()}
function attractionChange(){uxSheet({title:'修改游玩日期',fields:[{id:'newVisitDate',label:'新游玩日期',type:'date'}],confirmLabel:'查看改期方案',onConfirm:async v=>{const q=await api(`/v1/attractions/orders/${state.attractionOrder.order_id}/change-quote`,{method:'POST',body:JSON.stringify({new_visit_date:v.newVisitDate})});uxConfirm({title:'确认改期',description:'请确认新的日期与当前规则。',confirmLabel:'确认改期',onConfirm:async()=>{await api(`/v1/attractions/orders/${state.attractionOrder.order_id}/execute-change/${q.quote_id}`,{method:'POST'});await attractionReload()}})}})}
async function attractionRedeem(){try{await api(`/v1/attractions/orders/${state.attractionOrder.order_id}/redeem`,{method:'POST',body:JSON.stringify({evidence_reference:'CONSUMER_UI_REDEMPTION'})});await attractionReload()}catch(e){toast(e.message)}}
async function attractionRefund(){if(state.attractionOrder?.status==='REFUND_PENDING')return resumeVerticalRefund('ATTRACTION');try{const q=await api(`/v1/attractions/orders/${state.attractionOrder.order_id}/refund-quote`);if(!q.refundable){toast('该产品不可退款');return}uxConfirm({title:'申请门票退款',summary:`<div class="kv"><span>预计退款</span><b>${money(q.refund_amount_minor,q.currency)}</b></div>`,confirmLabel:'确认退款',danger:true,onConfirm:async()=>{await submitVerticalRefund('ATTRACTION',state.attractionOrder.order_id)}})}catch(e){toast(e.message)}}

bootstrapConsumer().finally(showHome);

function cancelUnpaidVertical(vertical){
 const o=vertical==='RAIL'?state.railOrder:state.attractionOrder;
 if(!o||o.status!=='PAYMENT_PENDING')return;
 const group=vertical==='RAIL'?'rail':'attractions';
 return uxConfirm({title:'取消未支付订单',description:'取消后将释放当前预留名额。如已开始支付，请先核对支付结果。',confirmLabel:'确认取消',danger:true,onConfirm:async()=>{
  try{await api(`/v1/${group}/orders/${encodeURIComponent(o.order_id)}/cancel-unpaid`,{method:'POST'})}
  finally{if(vertical==='RAIL')await railReload();else await attractionReload()}
 }});
}

function paymentDeadlineText(o){
 if(o?.unpaid_reservation_state==='EXPIRED')return '付款期限已到，未支付订单已取消，占位已释放。需要出行可重新选择。';
 if(o?.unpaid_reservation_state==='PAYMENT_STARTED')return '支付已开始，占位继续保留；处理结果未明时，请继续核对原支付。';
 if(o?.unpaid_reservation_state!=='OPEN'||o.status!=='PAYMENT_PENDING'||!Number.isSafeInteger(o.payment_deadline_ms)||o.payment_deadline_ms<=0||o.payment_deadline_ms>8640000000000000)return '';
 return `请在 ${new Date(o.payment_deadline_ms).toISOString().replace('T',' ').replace('.000Z',' UTC')} 前开始支付。逾期且未开始支付的订单将取消并释放占位。`;
}
function paymentDeadlineHtml(o){const text=paymentDeadlineText(o);return text?`<p class="muted" role="status">${safe(text)}</p>`:''}
